from pages import L,IG,FB,ADS,META,EU,STEPS
from pages5 import mk

DIRS=L('meta-appeal-links-and-forms-directory','Meta appeal links directory')
SEND='<h2 id="what-to-send-us">What to send us</h2><p>Message us on <a href="https://wa.me/19342012490">WhatsApp</a> or email <a href="mailto:team@unbanz.com">team@unbanz.com</a> with:</p><ul><li>The username or profile link.</li><li>A screenshot of the exact notice, with the date.</li><li>What you already tried (appeal, ID upload, verification).</li><li>Never your password or login codes.</li></ul>'

AQ=('Business Support Home (Account Quality)','https://business.facebook.com/accountquality','Shows restrictions on personal advertising access, Pages, ad accounts and Business Portfolios, with Request review where it is offered.')
BV=('Business verification','https://www.facebook.com/business/help/2058515294227817','Meta’s steps for verifying a Business Portfolio: documents, legal name and address must match.')
SAC=('Special Ad Categories','https://www.facebook.com/business/help/198009284345302','Housing, employment, credit and social issues, elections or politics. Ads in these areas have extra limits.')
HW=('Restricted content in ads','https://transparency.meta.com/policies/ad-standards/restricted-goods-services','Health, wellness and other restricted goods and services that need careful claims and targeting.')

PAGES=[
mk('facebook-restriction-says-final-no-explanation','Facebook Restriction Says Final With No Explanation: What to Check','Final restriction, no explanation',
 'Your Facebook or Meta restriction notice looks final and gives almost no reason. What Accounts Center, Account Status and support chat still offer, without promising a result.',
 'The restriction says final and there is no explanation.','The notice looks closed. Check these places before you assume nothing is left.',
 '<strong>A notice that says the decision is final, or that gives almost no reason, does not always mean every Meta screen is closed.</strong> Open Accounts Center on the same login, check Account Status or Business Support Home for a separate asset, and look for Meta support chat if you are an advertiser. Screenshot everything. Meta makes the final decision.',
 [('Read again','Final on one screen is not always final everywhere.'),('Accounts Center','Security, linked accounts, identity checks.'),('Support chat','Sometimes offered to advertisers only.')],
 '<h2 id="what-final-means">What “final” usually means</h2><ul><li>You already used the appeal on that notice, and Meta will not offer another one for the same decision.</li><li>The countdown or appeal window ended.</li><li>The wording is about one asset (for example a Page or ad account) while another asset still has a review button.</li></ul><p>See also '+L('guides/facebook-disabled-no-appeal-option','no appeal option')+', '+L('facebook-appeal-says-permanently-disabled','appeal says permanently disabled')+' and '+DIRS+'.</p>',
 [('check','Places to check anyway',[FB[0],FB[4],IG[3],AQ,ADS[3],META[0]])],
 [STEPS,'<h2 id="do-not">What not to do</h2><ul><li>Do not create a new profile to replace a disabled one.</li><li>There is no “private Meta link”.</li><li>Do not send passwords or codes to anyone who messages you.</li></ul>',SEND],
 DIRS+', '+L('how-to-contact-meta-about-a-disabled-account','how to contact Meta')+', '+L('how-to-tell-profile-vs-ad-account-vs-page-restriction','profile vs ad account vs Page')+'.',
 [('Does final mean Meta will never look again?','For that specific decision, Meta often offers no further in-product review. Other assets, Accounts Center or regional routes can still exist.'),('Should I email Meta?','Meta does not process account appeals by email. Use the in-product forms.'),('Is support chat a second appeal?','It is a help channel for some advertisers. It is not a private override of a final decision.')]),

mk('meta-business-verification-rejected-same-documents','Meta Business Verification Rejected With the Same Documents: What to Change','Verification rejected again',
 'Meta Business verification rejected the same documents you already uploaded. What usually mismatches, what to change before you try again, and where to upload.',
 'Business verification rejected the same documents again.','Re-uploading the same file rarely helps. Fix the mismatch first.',
 '<strong>If Meta rejected business verification with the same documents, change what does not match before you upload again.</strong> Common mismatches are legal name vs trading name, address vs registration address, blurry scans, expired IDs, or a document for a different country than the Business Portfolio. Upload once, clearly. Meta makes the final decision.',
 [('Match names','Legal name on the portfolio must match the document.'),('Clear scans','Full page, sharp, no crop.'),('One try','Fix first, then upload again.')],
 '<h2 id="what-to-change">What to change before trying again</h2><ol><li>Compare the Business Portfolio legal name with the name on the company document letter by letter.</li><li>Use the registered address Meta asks for, not a PO box or home address unless that is what the registry shows.</li><li>Upload a full, colour scan or photo of an official document Meta lists for your country (registry extract, tax letter, utility bill as allowed).</li><li>If a personal ID is required for an admin, use a current passport or government ID that matches the admin’s Facebook name.</li><li>Remove extra pages and screenshots of screenshots.</li></ol><p>Related: '+L('meta-business-verification-rejected','business verification rejected')+', '+L('ad-account-business-portfolio-verification-failed','portfolio verification failed')+'.</p>',
 [('links','Official verification links',[BV,AQ,ADS[3],ADS[0]])],
 [STEPS,SEND],
 DIRS+', '+L('meta-business-portfolio-appeal-links-directory','Business Portfolio appeal links')+', '+L('business-manager-disabled','Business Manager disabled')+'.',
 [('Can I keep uploading until it passes?','Repeated identical uploads usually stay rejected. Change the mismatch first.'),('Does verification restore a disabled ad account by itself?','Verification helps some portfolios, but a restricted ad account still needs its own review in Business Support Home.'),('Do I send documents to Unbanz?','No. Upload only inside Meta’s own verification flow.')]),

mk('facebook-page-unpublished-vs-account-disabled','Facebook Page Unpublished vs Account Disabled: How to Tell the Difference','Page unpublished vs account disabled',
 'Your Facebook Page disappeared or your profile will not open. How to tell an unpublished Page from a disabled personal account, and which official route applies.',
 'Is it an unpublished Page, or is the account disabled?','These look similar from the outside. The fix path is different.',
 '<strong>An unpublished Facebook Page is a business asset problem; a disabled account is a personal profile problem.</strong> If you can still log in to Facebook but the Page is gone or marked unpublished, use Business Support Home or Page Quality. If you cannot log into Facebook at all and see a disabled or suspended notice, appeal from that notice. Meta makes the final decision.',
 [('Still logged in','Likely the Page, not the profile.'),('Blocked at login','Likely the personal account.'),('Different forms','Page review vs profile appeal.')],
 '<h2 id="tell-apart">How to tell them apart</h2><ul><li><strong>Page unpublished:</strong> you open Facebook normally. The Page is missing from your list, shows as unpublished, or visitors see it as unavailable. Ads tied to that Page may stop. See '+L('facebook-business-page-unpublished-what-to-do','Page unpublished: what to do')+'.</li><li><strong>Account disabled:</strong> login shows a suspended or disabled message. Messenger and Instagram linked through Accounts Center can be affected too. See '+L('guides/facebook-account-disabled-appeal','Facebook disabled appeal')+'.</li><li><strong>Both at once:</strong> a disabled admin profile can make Pages look “lost” even when the Pages are fine. Other admins should check Business Support Home.</li></ul><p>Also see '+L('facebook-page-restricted-from-advertising-business','Page restricted from advertising')+' and '+L('how-to-tell-profile-vs-ad-account-vs-page-restriction','Account Quality layers')+'.</p>',
 [('links','Official links',[AQ,FB[0],ADS[0],ADS[3],FB[4]])],
 [STEPS,SEND],
 DIRS+', '+L('guides/facebook-page-restricted','Facebook Page restricted')+', '+L('facebook-disabled-page-admin-lost-pages','profile disabled, Pages lost')+'.',
 [('Can visitors still see an unpublished Page?','Usually no. Unpublished Pages are hidden from the public until restored.'),('Should I create a new Page?','Not while a review is open. A second Page can be restricted for the same reason.'),('Who requests a Page review?','A Page admin, from Business Support Home on a computer.')]),

mk('instagram-appeal-rejected-what-to-check-next','Instagram Appeal Rejected: What to Check Next','Appeal rejected, what next',
 'Instagram rejected your appeal for a disabled or suspended account. What to check next: Account Status, linked Facebook, EU routes, and what not to repeat.',
 'Instagram rejected the appeal. What should you check next?','Rejection is not always the end of every route. Check these points once, carefully.',
 '<strong>After Instagram rejects an appeal, do not submit the same appeal again.</strong> Check whether a linked Facebook profile is also disabled, whether Accounts Center shows a separate identity or security step, and whether you are in a region with an out-of-court option after Meta’s own process. Screenshot the rejection. Meta makes the final decision.',
 [('Stop repeating','Same appeal again rarely helps.'),('Linked accounts','Facebook or Threads may be involved.'),('Region routes','EU users may have a later option.')],
 '<h2 id="check-next">Checklist after a rejection</h2><ol><li>Screenshot the rejection screen and the original notice.</li><li>Try logging in on your usual phone and on a browser. Note whether any other button appears (it often does not).</li><li>Open Accounts Center from any working Meta login and check linked accounts and security.</li><li>If Facebook is also disabled, see '+L('facebook-and-instagram-disabled-together-linked-accounts','Facebook and Instagram disabled together')+'.</li><li>If the notice ever offered no button, see '+L('instagram-disabled-no-appeal-button-what-to-do','no appeal button')+'.</li><li>In the EU, after Meta’s appeal is finished, look at '+L('appeals-centre-europe-instagram-facebook-suspension','Appeals Centre Europe')+'.</li></ol><p>Sibling pages: '+L('instagram-appeal-denied','Instagram appeal denied')+', '+L('guides/instagram-appeal-sent-no-response','appeal sent, no response')+'.</p>',
 [('links','Official links',IG[:4]+EU[:1]+[META[0]])],
 [STEPS,'<h2 id="avoid">Avoid these next</h2><ul><li>New accounts on the same phone or email while you wait.</li><li>Buying a “restore” from someone in your DMs.</li><li>Long legal letters emailed to Meta. Meta does not process those.</li></ul>',SEND],
 DIRS+', '+L('instagram-appeal-links-and-forms-directory','Instagram appeal links')+', '+L('guides/instagram-account-suspended-appeal','Instagram suspended appeal')+'.',
 [('Can I appeal the rejection?','Instagram usually does not offer a second appeal for the same decision. Check other assets and regional routes instead.'),('Does Meta Verified reopen a rejected appeal?','Meta Verified can open a support chat for subscribers. It does not replace the disabled-account decision.'),('Should I delete the app and reinstall?','That does not change the decision. Keep screenshots first.')]),

mk('meta-ad-account-sensitive-categories-restriction','Meta Ad Account Restricted for Sensitive Categories: Health, Housing, Finance','Sensitive category restriction',
 'Meta restricted your ad account or ads after health and wellness, housing, employment, credit or other sensitive-category ads. What Special Ad Categories require and how to request a review honestly.',
 'Restricted after sensitive-category ads. What now?','Health, housing, finance and similar ads have extra rules. Fix the ad setup before you request a review.',
 '<strong>A Meta ad account restricted after sensitive-category ads usually needs the ads and landing pages fixed first, then one clear request for review in Business Support Home.</strong> Special Ad Categories (housing, employment, credit, social issues, elections or politics) limit targeting. Health and wellness ads face claim and before-and-after limits. Do not open a new ad account to get around it. Meta makes the final decision.',
 [('Fix ads first','Claims, landing page, category.'),('Special Ad Categories','Use the correct declaration.'),('One review','Business Support Home, once.')],
 '<h2 id="what-counts">What counts as sensitive here</h2><ul><li><strong>Special Ad Categories:</strong> housing, employment, credit, and social issues, elections or politics. Wrong targeting or missing declaration is a common trigger.</li><li><strong>Health and wellness:</strong> cure claims, before-and-after body images, personal-attribute targeting. See also '+L('ad-account-restricted-ads-for-health-and-wellness-businesses','health and wellness ads restricted')+'.</li><li><strong>Finance and products:</strong> '+L('ad-account-restricted-financial-products-and-services-ads','financial products ads')+'.</li></ul><h2 id="before-review">Before you request a review</h2><ol><li>Open Business Support Home and read the exact reason.</li><li>Pause or edit the ads named in the notice.</li><li>Align the landing page with the ad: contact details, policy pages, no bait claims.</li><li>Confirm Special Ad Category is set correctly if the offer falls in those areas.</li><li>Request a review once and say what you changed.</li></ol><p>More: '+L('meta-ad-account-fix-the-cause-before-appeal','fix the cause before you appeal')+', '+L('guides/meta-ad-account-restricted','Meta ad account restricted guide')+'.</p>',
 [('links','Official links',[AQ,ADS[0],ADS[1],SAC,HW,ADS[4]])],
 [STEPS,SEND],
 DIRS+', '+L('meta-ad-account-appeal-links-directory','Meta ad account appeal links')+', '+L('ad-account-restricted-personal-attributes','personal attributes restriction')+'.',
 [('Will choosing Special Ad Categories fix a restriction by itself?','No. You still need compliant ads and, if offered, a request for review.'),('Can I keep running non-sensitive ads on the same account?','If the whole ad account is restricted, no ads run until that restriction is cleared.'),('Is a new Business Portfolio safer?','Creating new portfolios or ad accounts to avoid a restriction can be treated as circumventing systems.')]),

mk('how-to-tell-profile-vs-ad-account-vs-page-restriction','How to Tell Profile vs Ad Account vs Page Restriction (Account Quality)','Profile vs ad account vs Page',
 'Meta Account Quality can show restrictions on a personal profile, an ad account, a Page or a Business Portfolio. How to tell which layer is hit and which review to use.',
 'Which Meta restriction do you actually have?','Profile, Page, ad account and portfolio use different buttons. Start by naming the layer.',
 '<strong>Open Business Support Home (Account Quality) on a computer and read which asset is listed.</strong> A personal profile advertising restriction is different from a disabled Facebook login, a Page unpublished or restricted from ads, and a disabled ad account. Each has its own request-review path. Fix and appeal the asset that is actually named. Meta makes the final decision.',
 [('Name the asset','Profile, Page, ad account or portfolio.'),('One screen','Business Support Home lists them.'),('Right button','Do not use a profile appeal for ads.')],
 '<h2 id="layers">The layers you will see</h2><ul><li><strong>Personal profile / advertising access:</strong> you can log into Facebook, but you cannot create or manage ads. Review from Account Quality against your person.</li><li><strong>Disabled or suspended profile:</strong> you cannot log in. Appeal from the login notice, not Account Quality. See '+L('guides/facebook-account-disabled-appeal','Facebook disabled appeal')+'.</li><li><strong>Page:</strong> unpublished, restricted from advertising, or other Page Quality issues. See '+L('facebook-page-unpublished-vs-account-disabled','Page unpublished vs account disabled')+' and '+L('facebook-page-restricted-from-advertising-business','Page restricted from advertising')+'.</li><li><strong>Ad account:</strong> restricted or disabled; ads stop. See '+L('guides/meta-ad-account-restricted','ad account restricted')+'.</li><li><strong>Business Portfolio:</strong> many assets can stop together. See '+L('meta-business-portfolio-restricted-help','Business Portfolio restricted')+'.</li></ul><h2 id="steps">Steps</h2><ol><li>Screenshot Account Quality with the asset name visible.</li><li>Check whether login still works.</li><li>Only then open the matching review.</li><li>Official forms: '+DIRS+'.</li></ol>',
 [('links','Official links',[AQ,ADS[0],ADS[1],FB[0],ADS[3]])],
 [STEPS,SEND],
 DIRS+', '+L('meta-ad-account-restricted-vs-disabled','restricted vs disabled')+', '+L('facebook-notice-types','Facebook notice types')+'.',
 [('Why does Account Quality show nothing?','You may not be an admin, or the problem is a disabled personal login rather than an ads asset.'),('Can one review clear everything?','No. Each restricted asset needs its own path.'),('Does Instagram use Account Quality?','Instagram profile issues use Account Status in the app. Ads and Business Portfolio still use Business Support Home.')]),

mk('facebook-hacked-then-disabled-same-day','Facebook Hacked Then Disabled the Same Day: What to Do','Hacked then disabled same day',
 'Your Facebook account was hacked and disabled on the same day. Which notice to follow first, how to use facebook.com/hacked, and what to avoid while you appeal.',
 'Hacked and disabled on the same day. Where do you start?','Takeover and disable often arrive together. Order matters.',
 '<strong>If Facebook was hacked and then disabled the same day, treat it as a takeover that triggered a disable.</strong> Screenshot every screen, try facebook.com/hacked if you cannot reach the disabled notice, and use the disabled-account appeal from the login message when it appears. Say the account was taken over and used without you. Do not create a replacement profile. Meta makes the final decision.',
 [('Screenshot','Every notice and email.'),('Hacked page','If login details changed.'),('One appeal','Explain the takeover briefly.')],
 '<h2 id="order">Order of steps</h2><ol><li>Write down what changed: email, phone, name, password, posts or ads you did not make.</li><li>Open <a href="https://www.facebook.com/hacked" rel="noopener" target="_blank">facebook.com/hacked</a> and the disabled notice if shown.</li><li>Appeal once from the disabled screen: you are the owner, the account was taken over, and you want it secured and restored.</li><li>Alert friends that scam messages were not from you.</li><li>If a Business Portfolio gained an unknown admin, see '+L('facebook-hacked-business-portfolio-unknown-admin','unknown admin after a hack')+'.</li></ol><p>Related: '+L('facebook-disabled-after-hack-used-for-spam','hacked then disabled for spam')+', '+L('guides/hacked-facebook-account-recovery','hacked Facebook recovery')+', '+L('instagram-account-disabled-after-hack-appeal','Instagram disabled after hack')+'.</p>',
 [('links','Official links',[FB[1],FB[0],FB[2],META[0],AQ])],
 [STEPS,'<h2 id="avoid">Avoid</h2><ul><li>Paying a stranger who claims they can “unlock” Facebook.</li><li>Logging in from random VPNs while appealing.</li><li>Opening a second profile that posts as you.</li></ul>',SEND],
 DIRS+', '+L('facebook-appeal-links-and-forms-directory','Facebook appeal links')+', '+L('guides/facebook-account-disabled-appeal','Facebook disabled appeal')+'.',
 [('Why disable after a hack?','Taken-over accounts are often used for spam or scams, which can trigger a disable.'),('Should I reset the password first?','If you can still reset and get in, secure email and phone first. If you only see the disabled notice, use that appeal.'),('Do I need a police report?','Useful for your own records and banks if money moved. Meta’s appeal still runs through its own forms.')]),

mk('facebook-account-disabled-singapore-what-to-do','Facebook Account Disabled in Singapore: What to Do','Facebook disabled, Singapore',
 'Your Facebook account was disabled and you are in Singapore. How to appeal from the notice, which ID to prepare, and local places to report hacking or scams.',
 'Facebook disabled your account and you are in Singapore?','Appeal from the login notice, prepare a clear ID if asked, and use local reporting if you were scammed.',
 '<strong>If Facebook disabled your account and you are in Singapore, appeal from the notice shown when you log in, on your usual phone, without a VPN.</strong> Screenshot the message, submit one short factual appeal, and complete any ID or video selfie step Meta shows. For a hack, also use facebook.com/hacked. Meta makes the final decision.',
 [('Appeal in-app','From the disabled notice.'),('Usual device','No VPN for the appeal.'),('Local help','Report scams to Singapore channels.')],
 '<h2 id="steps-sg">Steps in Singapore</h2><ol><li>Screenshot the full disabled or suspended message.</li><li>Tap to disagree or appeal. Write who you are and that the profile is yours.</li><li>If Meta asks for ID, use a current NRIC, FIN or passport that matches the name on the profile, in good light.</li><li>If email or phone changed without you, use facebook.com/hacked as well.</li><li>Do not give your login to anyone offering a private restore.</li></ol><p>Country siblings: '+L('facebook-account-disabled-australia-what-to-do','Australia')+', '+L('facebook-account-disabled-uae-what-to-do','UAE')+', '+L('facebook-account-disabled-uk-what-to-do','UK')+'. All forms: '+DIRS+'.</p>',
 [('fb','Facebook and Meta',[FB[0],FB[1],FB[2],META[0],META[2]]),
  ('sg','Singapore reporting',[('ScamShield / scam reporting','https://www.scamshield.gov.sg/','Official Singapore channel for reporting scams, including account-takeover scams.'),('Singapore Police Force e-services','https://www.police.gov.sg/','For filing a report when a hacked account was used for fraud or money loss.'),('PDPC','https://www.pdpc.gov.sg/','Personal data protection guidance if your data was misused.')])],
 [STEPS,SEND],
 DIRS+', '+L('guides/facebook-account-disabled-appeal','Facebook disabled appeal')+', '+L('meta-appeal-links-australia','Meta appeal links for Australia')+'.',
 [('Which ID should I upload in Singapore?','Use a current government ID Meta accepts that matches the name on the Facebook profile, such as NRIC, FIN or passport.'),('Is there a Meta phone number in Singapore?','Meta has no general public phone line for account appeals. Numbers claiming to be Meta support are often scams.'),('Can I use a VPN from Singapore?','For the appeal, use your normal connection. VPNs can look like suspicious logins.')]),
]
